style.css:
@-moz-document domain("drive.google.com") {
/* Main background */
    body, .a-s-tb-sc, .a-Ue-vd, .a-s-fa-Ba, .a-s-Ma-U {
        background-color: #150018 !important; /* very dark purple */
        color: #e8d9ff !important; /* soft lavender text */
    }

    /* Sidebar + menus */
    .a-s-fa-Ba, .a-s-fa-tc, .a-s-fa-Fe {
        background-color: #240033 !important; /* dark purple menus */
        color: #f0e6ff !important;
    }

    /* Hover effect */
    .a-s-fa-Fe:hover, .a-s-fa-tc:hover {
        background-color: #4b0073 !important;
        color: #ffffff !important;
    }

    /* Selected item */
    .a-s-fa-Fe-selected, .a-s-fa-Ba .a-s-fa-Fe-selected {
        background-color: #660099 !important;
        color: #ffffff !important;
    }

    /* Toolbar */
    .a-s-fa-ld {
        background-color: #1e002b !important;
    }

    /* Search bar */
    .a-s-vc {
        background-color: #2f0044 !important;
        color: #e8d9ff !important;
        border: 1px solid #660099 !important;
    }

    /* File list background */
    .a-D-Ba, .a-s-Ba {
        background-color: #1a001f !important;
        color: #e8d9ff !important;
    }
}
